{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Connect — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7faf7;--card:#ffffff;--muted:#6b7280;--brand:#6b3dd1;--accent:#ff9f7a;--glass:rgba(255,255,255,0.7)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0f172a;background:var(--bg);}
    body{display:flex;flex-direction:column}
    header{background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(6px);position:sticky;top:0;z-index:20;border-bottom:1px solid rgba(15,23,42,0.04)}
    .wrap{max-width:1100px;margin:0 auto;padding:18px}
    nav{display:flex;gap:22px;align-items:center}
    nav a{color:#0f172a;text-decoration:none;font-weight:600}
    .brand{font-weight:700;color:var(--brand)}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;padding:48px 0;align-items:start}
    .hero-card{background:var(--card);border-radius:14px;padding:28px;box-shadow:0 6px 20px rgba(13,17,33,0.07);position:relative;overflow:hidden}
    .pattern{position:absolute;inset:0;opacity:0.06;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    /* Pricing toggle */
    .pricing-toggle{display:flex;flex-direction:column;gap:12px;padding:14px;border-radius:10px;background:linear-gradient(180deg,rgba(107,61,209,0.03),transparent);border:1px solid rgba(107,61,209,0.06)}
    .toggle-row{display:flex;align-items:center;gap:8px}
    .switch{background:#e6e9f7;border-radius:999px;padding:4px;display:inline-flex;gap:6px}
    .switch button{background:transparent;border:0;padding:8px 10px;border-radius:999px;cursor:pointer;font-weight:600}
    .switch button.active{background:var(--brand);color:#fff}
    .price{font-size:22px;font-weight:700;color:var(--brand)}
    .small{font-size:13px;color:var(--muted)}

    /* Form */
    form{display:grid;gap:12px}
    input,select,textarea{width:100%;padding:12px;border-radius:8px;border:1px solid rgba(15,23,42,0.06);font-size:15px}
    button.cta{background:var(--brand);color:#fff;border:0;padding:12px 16px;border-radius:10px;font-weight:700;cursor:pointer}

    /* Proof gallery */
    .proof{display:grid;grid-template-columns:1fr 260px;gap:20px;padding:28px 0}
    .testimonial{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 26px rgba(11,15,30,0.06);min-height:120px;display:flex;flex-direction:column;justify-content:center}
    .quote{font-style:italic;margin:0 0 8px}
    .who{font-weight:700;color:var(--brand);font-size:14px}
    .badges{display:flex;flex-direction:column;gap:12px}
    .badge{display:flex;gap:8px;align-items:center;padding:8px;border-radius:8px;background:linear-gradient(90deg,rgba(255,255,255,0.5),transparent);cursor:default;position:relative}
    .badge svg{width:36px;height:36px}
    .badge .meta{font-size:13px;color:var(--muted)}
    .tooltip{position:absolute;left:calc(100% + 8px);top:50%;transform:translateY(-50%);background:#111827;color:#fff;padding:8px;border-radius:8px;white-space:nowrap;font-size:13px;opacity:0;pointer-events:none;transition:opacity .18s}
    .badge:hover .tooltip{opacity:1}

    /* Footer */
    footer{padding:28px 0;color:var(--muted);font-size:14px}

    @media (max-width:880px){
      .hero{grid-template-columns:1fr;}
      .proof{grid-template-columns:1fr}
    }
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <div class="brand">{{BUSINESS_NAME}}</div>
        <a href="index.html">Welcome</a>
        <a href="about.html">Approach</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Packages</a>
        <a href="testimonials.html">Proof</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero">
      <div class="hero-card">
        <div class="pattern" aria-hidden="true"></div>
        <h1>Let’s craft steady days that fit your life</h1>
        <p class="lead">I help busy people translate goals into small, repeatable habits that actually stick. Tell me what’s pressing, and we’ll design a short plan you can use the very next day.</p>
        <div style="height:16px"></div>
        <div style="display:flex;gap:10px">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a href="tel:{{PHONE}}" style="display:inline-flex;align-items:center;padding:10px 12px;border-radius:10px;border:1px solid rgba(15,23,42,0.06);text-decoration:none;color:var(--muted)">Call: {{PHONE}}</a>
        </div>
        <div style="height:18px"></div>
        <div class="pricing-toggle">
          <div class="toggle-row">
            <div class="small">Pricing preview</div>
            <div style="flex:1"></div>
            <div class="switch" role="tablist" aria-label="Pricing toggle">
              <button data-mode="monthly" class="active">Monthly</button>
              <button data-mode="package">Cohort</button>
            </div>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div class="price" data-price>—</div>
              <div class="small">per person</div>
            </div>
            <div class="small">Includes rhythm workbook &amp; a 4-week guided cohort</div>
          </div>
        </div>
      </div>

      <aside>
        <div class="hero-card">
          <h3>Get in touch</h3>
          <p class="small">Prefer a note? Drop a quick message and I’ll reply in 48 hours.</p>
          <form id="contactForm">
            <input type="text" name="name" placeholder="Your name" required>
            <input type="email" name="email" placeholder="Email" required>
            <select name="interest">
              <option value="rhythm">Rhythm Cohort — steady mornings</option>
              <option value="reset">Reset Residency — short reboot</option>
              <option value="forge">Habit Forge — one habit at a time</option>
            </select>
            <textarea name="message" rows="4" placeholder="What would you like to focus on? (optional)"></textarea>
            <button type="submit" class="cta">Send message</button>
          </form>
          <div style="height:12px"></div>
          <div class="small">Or email directly: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </aside>
    </section>

    <section class="proof">
      <div>
        <div class="testimonial" id="testimonial">
          <p class="quote" id="test-quote">“Starting small made everything possible. I actually keep going.”</p>
          <div class="who" id="test-who">— A. Participant</div>
        </div>
        <div style="height:12px"></div>
        <div class="small">Testimonials rotate every few seconds. Hover each badge for context.</div>
      </div>

      <div class="badges" id="badges">
        <div class="badge" tabindex="0">
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" stroke="#6b3dd1" stroke-width="1.5" fill="#fff"/><path d="M7 12l3 3 7-7" stroke="#6b3dd1" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>
          <div>
            <div style="font-weight:700">Evidence-backed</div>
            <div class="meta">Practice frameworks, not fads</div>
          </div>
          <div class="tooltip">Frameworks shaped from habit research and client cycles</div>
        </div>

        <div class="badge" tabindex="0">
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect x="3" y="6" width="18" height="12" rx="2" stroke="#ff9f7a" stroke-width="1.5" fill="#fff"/><path d="M8 10h8" stroke="#ff9f7a" stroke-width="1.5" stroke-linecap="round"/></svg>
          <div>
            <div style="font-weight:700">Cohort format</div>
            <div class="meta">Peer rhythm, guided weeks</div>
          </div>
          <div class="tooltip">Run in small groups with live check-ins and shared templates</div>
        </div>

        <div class="badge" tabindex="0">
          <svg viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 3v18" stroke="#10b981" stroke-width="1.6" stroke-linecap="round"/><path d="M6 9h12" stroke="#10b981" stroke-width="1.6" stroke-linecap="round"/></svg>
          <div>
            <div style="font-weight:700">Habit tools</div>
            <div class="meta">Checklists & trackers</div>
          </div>
          <div class="tooltip">Reusable tools to embed new practices into your week</div>
        </div>
      </div>
    </section>

    <section style="padding:18px 0;display:flex;gap:18px;align-items:center">
      <div style="flex:1"></div>
      <div class="hero-card" style="width:360px">
        <h4 style="margin:0 0 8px">Quick price compare</h4>
        <div class="pricing-toggle">
          <div class="toggle-row">
            <div class="small">Choose a view</div>
            <div style="flex:1"></div>
            <div class="switch" aria-hidden="true">
              <button data-mode="monthly" class="active">Monthly</button>
              <button data-mode="package">Package</button>
            </div>
          </div>
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div class="price" data-price-2>—</div>
              <div class="small">per person</div>
            </div>
            <div class="small">Quick glance for planning</div>
          </div>
        </div>
        <div style="height:12px"></div>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer>
    <div class="wrap">
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
        <div style="color:var(--muted)">Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> • <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div style="color:var(--muted)">© <span id="year"></span> {{BUSINESS_NAME}} — small commitments, steady results</div>
      </div>
    </div>
  </footer>

  <script>
    // Year
    document.getElementById('year').textContent = new Date().getFullYear();

    // Testimonial rotation (Proof Gallery)
    (function(){
      const items = [
        {quote: 'I can actually keep one morning habit going. The group check-ins make it stick.', who: 'Maya, Product Designer'},
        {quote: 'Short weekly steps shifted my energy. It felt designed for my schedule.', who: 'Carlos, Teacher'},
        {quote: 'The workbook and tiny experiments helped me build a reliable routine.', who: 'Sam, Freelancer'}
      ];
      let idx = 0; const qEl = document.getElementById('test-quote'); const wEl = document.getElementById('test-who');
      function show(i){
        qEl.style.opacity = 0; wEl.style.opacity = 0;
        setTimeout(()=>{ qEl.textContent = '“'+items[i].quote+'”'; wEl.textContent = '— '+items[i].who; qEl.style.opacity = 1; wEl.style.opacity = 1; },250);
      }
      show(0); setInterval(()=>{ idx=(idx+1)%items.length; show(idx); },5000);
    })();

    // Pricing Comparator logic + animated numbers
    (function(){
      const modes = document.querySelectorAll('.switch button');
      const priceEl = document.querySelector('[data-price]');
      const priceEl2 = document.querySelector('[data-price-2]');
      // Unique pricing framing
      const pricing = { monthly:39, package:295 };
      function animateValue(el,start,end,duration){
        const range = end - start; let startTime = null;
        function step(timestamp){
          if(!startTime) startTime = timestamp;
          const progress = Math.min((timestamp - startTime)/duration,1);
          const value = Math.round(start + range * easeOutCubic(progress));
          el.textContent = '$' + value + (el===priceEl ? '/mo' : (currentMode==='monthly' ? '/mo' : ' / cohort'));
          if(progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }
      function easeOutCubic(t){ return 1 - Math.pow(1-t,3); }
      let currentMode = 'monthly';

      function setMode(mode){
        if(mode===currentMode) return;
        const before = pricing[currentMode];
        const after = pricing[mode];
        currentMode = mode;
        // update button active states
        document.querySelectorAll('.switch button').forEach(b=> b.classList.toggle('active', b.dataset.mode===mode));
        // animate both price displays (if present)
        animateValue(priceEl, before, after, 550);
        animateValue(priceEl2, before, after, 650);
      }

      // initial render
      priceEl.textContent = '$' + pricing.monthly + '/mo';
      priceEl2.textContent = '$' + pricing.monthly + '/mo';

      document.querySelectorAll('.switch button').forEach(btn=>{
        btn.addEventListener('click',()=>{
          const m = btn.dataset.mode;
          setMode(m);
        });
      });
    })();

    // Simple form handler
    (function(){
      const form = document.getElementById('contactForm');
      form.addEventListener('submit', function(e){
        e.preventDefault();
        const data = new FormData(form);
        const name = data.get('name');
        const email = data.get('email');
        const interest = data.get('interest');
        const message = data.get('message') || '';
        // Minimal send: open user's email client with a draft (local)
        const subject = encodeURIComponent('Inquiry from '+name+' — '+interest);
        const body = encodeURIComponent('Name: '+name+'\nEmail: '+email+'\nInterest: '+interest+'\n\n'+message);
        window.location.href = 'mailto:{{EMAIL}}?subject='+subject+'&body='+body;
      });
    })();
  </script>
</body>
</html>"} 
